def choose_move(observation):
    # Deterministic, simple heuristic: move toward the opponent if available; otherwise stay.
    ox = observation.get("opponent_position", {}).get("x", 0)
    oy = observation.get("opponent_position", {}).get("y", 0)
    sx = observation.get("self_position", {}).get("x", 0)
    sy = observation.get("self_position", {}).get("y", 0)

    dx = 0
    dy = 0

    if ox is not None and oy is not None:
        if ox > sx:
            dx = 1
        elif ox < sx:
            dx = -1
        else:
            dx = 0

        if oy > sy:
            dy = 1
        elif oy < sy:
            dy = -1
        else:
            dy = 0
    else:
        dx = 0
        dy = 0

    # Clamp to -1,0,1 and ensure final is an int pair
    if dx not in (-1, 0, 1): dx = 0
    if dy not in (-1, 0, 1): dy = 0

    return [dx, dy]
